  @Test
  void errorCodesAndFactory() {
    Duration second = Duration.ofSeconds(1);
    RuntimeException cause = new RuntimeException();
    for (ErrorCode c : ErrorCode.values()) {
      ZipkinException e = ZipkinException.of(c, "m", 418, "r", second, cause);
      assertThat(e.code()).isEqualTo(c);
      assertThat(e.getClass().getSimpleName()).isNotEqualTo("ZipkinException");
      assertThat(e.retryable()).isEqualTo(c.retryable());
      assertThat(e.httpStatus()).hasValue(418);
      assertThat(e.requestId()).contains("r");
      assertThat(e.retryAfter()).contains(Duration.ofSeconds(1));
      assertThat(e.code().wireValue()).isEqualTo(c.name());
    }
    ZipkinException plain = new ConfigException("x");
    assertThat(plain.httpStatus()).isEmpty();
    assertThat(plain.requestId()).isEmpty();
    assertThat(plain.retryAfter()).isEmpty();
    assertThat(new NotFoundException("x", new IllegalStateException()).getCause())
        .isInstanceOf(IllegalStateException.class);
    List<ZipkinException> all =
        List.of(
            new AuthenticationException("a"),
            new AuthenticationException("a", null),
            new PermissionDeniedException("a"),
            new PermissionDeniedException("a", null),
            new ConflictException("a"),
            new ConflictException("a", null),
            new RateLimitException("a"),
            new RateLimitException("a", null),
            new ValidationException("a"),
            new UnavailableException("a"),
            new TimeoutException("a"),
            new TimeoutException("a", null),
            new UnsupportedException("a"),
            new UnsupportedException("a", null),
            new CancelledException("a"),
            new ConfigException("a", null));
    assertThat(all).allSatisfy(e -> assertThat(e.getMessage()).isEqualTo("a"));
  }

  @Test
  void secretNeverPrints() {
    Secret s = Secret.of("hunter22");
    assertThat(s.toString()).isEqualTo("[REDACTED]");
    assertThat(Json.stringify(Map.of("t", s))).isEqualTo("{\"t\":\"[REDACTED]\"}");
    assertThat(s.reveal()).isEqualTo("hunter22");
    assertThat(s.revealChars()).containsExactly('h', 'u', 'n', 't', 'e', 'r', '2', '2');
    assertThat(s.isEmpty()).isFalse();
    assertThat(Secret.of(new char[0]).isEmpty()).isTrue();
    assertThat(s.sameValue(Secret.of("hunter22"))).isTrue();
    assertThat(s.sameValue(Secret.of("hunter2"))).isFalse();
    assertThat(s.sameValue(Secret.of("hunter23"))).isFalse();
    s.clear();
    s.clear();
    assertThat(s.isCleared()).isTrue();
    assertThatThrownBy(s::reveal).isInstanceOf(IllegalStateException.class);
  }

