  @Test
  void transportRequestAndConfigAccessors() {
    TransportRequest r =
        TransportRequest.builder("patch", "/p")
            .body(new byte[] {1, 2}, "application/octet-stream")
            .acceptAnyStatus()
            .build();
    assertThat(r.method()).isEqualTo("PATCH");
    assertThat(r.path()).isEqualTo("/p");
    assertThat(r.query()).isEmpty();
    assertThat(r.headers()).isEmpty();
    assertThat(r.body()).hasValueSatisfying(b -> assertThat(b).containsExactly(1, 2));
    assertThat(r.contentType()).contains("application/octet-stream");
    assertThat(r.idempotent()).isFalse();
    assertThat(r.operation()).isEqualTo("PATCH /p");
    assertThat(r.accepts(500)).isTrue();
    assertThat(r.maxRetries()).isEmpty();
    assertThat(r.timeout()).isEmpty();
    assertThat(TransportRequest.put("/x").build().idempotent()).isTrue();
    assertThat(TransportRequest.delete("/x").build().idempotent()).isTrue();
    assertThat(TransportRequest.get("/x").build().body()).isEmpty();
    assertThat(TransportRequest.get("/x").build().accepts(404)).isFalse();
    TransportConfig c = TransportConfig.builder("http://h").knownSecrets(() -> null).build();
    assertThat(c.knownSecrets()).isEmpty();
    assertThat(c.baseUrl()).isEqualTo("http://h");
    assertThat(c.connectTimeout()).isEqualTo(Duration.ofSeconds(10));
    assertThat(c.requestTimeout()).isEqualTo(Duration.ofSeconds(30));
    assertThat(c.totalTimeout()).isEqualTo(Duration.ofSeconds(120));
    assertThat(c.proxy()).isEmpty();
    assertThat(c.headers()).isEmpty();
    assertThat(c.userAgentSuffix()).isEmpty();
    assertThat(c.retry().maxRetries()).isEqualTo(3);
    assertThat(c.tls().isCustom()).isFalse();
    assertThat(c.clock()).isNotNull();
    assertThat(TransportConfig.builder("http://h").userAgentSuffix(" ").build().userAgent())
        .isEqualTo(SdkInfo.userAgent());
  }

  @Test
  void pollUntil() {
    AtomicInteger n = new AtomicInteger();
    assertThat(
            Poll.until(
                "op",
                Duration.ofSeconds(2),
                Duration.ofMillis(5),
                () -> {
                  int i = n.incrementAndGet();
                  if (i == 1) {
                    throw new UnavailableException("transient");
                  }
                  return i >= 3 ? Optional.of("done") : Optional.empty();
                }))
        .isEqualTo("done");
    assertThatThrownBy(
            () ->
                Poll.until(
                    "wait",
                    Duration.ofMillis(50),
                    Duration.ofMillis(10),
                    () -> {
                      throw new UnavailableException("still down");
                    }))
        .isInstanceOf(TimeoutException.class)
        .hasMessageContaining("wait: condition not met within 50 ms")
        .hasCauseInstanceOf(UnavailableException.class);
    assertThatThrownBy(
            () ->
                Poll.until(
                    "op",
                    Duration.ofSeconds(1),
                    Duration.ofMillis(10),
                    () -> {
                      throw new NotFoundException("fatal");
                    }))
        .isInstanceOf(NotFoundException.class);
    assertThatThrownBy(
            () ->
                Poll.until(
                    "op",
                    Duration.ofSeconds(1),
                    Duration.ofMillis(10),
                    () -> {
                      throw new java.io.IOException("io");
                    }))
        .isInstanceOf(UnavailableException.class);
    assertThatThrownBy(
            () ->
                Poll.until(
                    "op",
                    Duration.ofSeconds(1),
                    Duration.ofMillis(10),
                    () -> {
                      throw new InterruptedException();
                    }))
        .isInstanceOf(CancelledException.class);
    Thread.interrupted();
    Thread.currentThread().interrupt();
    assertThatThrownBy(
            () -> Poll.until("op", Duration.ofSeconds(1), Duration.ofMillis(100), Optional::empty))
        .isInstanceOf(CancelledException.class);
    assertThat(Thread.interrupted()).isTrue();
  }

  @Test
  void pollUntilAsync() {
    AtomicInteger n = new AtomicInteger();
    CompletableFuture<String> ok =
        Poll.untilAsync(
            "op",
            Duration.ofSeconds(2),
            Duration.ofMillis(5),
            () -> {
              int i = n.incrementAndGet();
              if (i == 1) {
                return CompletableFuture.failedFuture(new UnavailableException("transient"));
              }
              if (i == 2) {
                throw new UnavailableException("thrown");
              }
              return CompletableFuture.completedFuture(
                  i >= 4 ? Optional.of("x") : Optional.empty());
            });
    assertThat(ok.join()).isEqualTo("x");
    CompletableFuture<String> timeout =
        Poll.untilAsync(
            "op",
            Duration.ofMillis(40),
            Duration.ofMillis(10),
            () -> CompletableFuture.completedFuture(Optional.empty()));
    assertThatThrownBy(() -> HttpTransport.await(timeout, "op"))
        .isInstanceOf(TimeoutException.class);
    CompletableFuture<String> fatal =
        Poll.untilAsync(
            "op",
            Duration.ofSeconds(1),
            Duration.ofMillis(10),
            () -> CompletableFuture.failedFuture(new NotFoundException("nf")));
    assertThatThrownBy(() -> HttpTransport.await(fatal, "op"))
        .isInstanceOf(NotFoundException.class);
    CompletableFuture<String> cancelled =
        Poll.untilAsync(
            "op",
            Duration.ofSeconds(5),
            Duration.ofMillis(20),
            () -> CompletableFuture.completedFuture(Optional.empty()));
    cancelled.cancel(true);
    assertThat(cancelled.isCancelled()).isTrue();
  }

  @Test
  void quietJulKeepsSilencedLoggersReachable() {
    String name = "grow.test.quiet." + System.nanoTime();
    QuietJul.silence(name);
    // JUL holds loggers weakly: without the helper's strong reference a GC would drop the level
    for (int i = 0; i < 3; i++) {
      System.gc();
    }
    assertThat(java.util.logging.Logger.getLogger(name).getLevel())
        .isEqualTo(java.util.logging.Level.OFF);
    assertThat(QuietJul.level(name, null).getLevel()).isNull();
    assertThat(QuietJul.level(name, java.util.logging.Level.FINE))
        .isSameAs(java.util.logging.Logger.getLogger(name));
    assertThatThrownBy(() -> QuietJul.level(null, null)).isInstanceOf(NullPointerException.class);
  }
